import React from 'react';

interface CategoryBrowseProps {
  categories: { label: string; href: string }[];
}

export const CategoryBrowse: React.FC<CategoryBrowseProps> = ({ categories }) => {
  return (
    <section className="job10-category-browse" id="categories" aria-label="Browse by category">
      <div className="job10-container">
        <div className="job10-category-browse-inner">
          <span className="job10-category-label">Popular Categories:</span>
          <nav className="job10-category-links" aria-label="Job categories">
            {categories.map((cat, idx) => (
              <a key={idx} href={cat.href} className="job10-category-link">
                {cat.label}
              </a>
            ))}
          </nav>
        </div>
      </div>
    </section>
  );
};
