'use client';

import React, { useState, useEffect } from 'react';
import { Job10Logo } from './Job10Logo';
import type { NavItem } from '@/config/campaign.types';

interface CampaignHeaderProps {
  navItems: NavItem[];
  ctaLabel: string;
  ctaHref: string;
  onAudienceSelect?: (audience: 'jobseeker' | 'recruiter') => void;
}

export const CampaignHeader: React.FC<CampaignHeaderProps> = ({
  navItems,
  ctaLabel,
  ctaHref,
  onAudienceSelect,
}) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 40);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleNavClick = (href: string, e: React.MouseEvent) => {
    if (href.includes('jobseeker') && onAudienceSelect) {
      e.preventDefault();
      onAudienceSelect('jobseeker');
      const el = document.getElementById('action-panel');
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    } else if (href.includes('recruiter') && onAudienceSelect) {
      e.preventDefault();
      onAudienceSelect('recruiter');
      const el = document.getElementById('action-panel');
      if (el) el.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <header className={`job10-header ${isScrolled ? 'scrolled' : ''}`}>
      <div className="job10-container">
        <div className="job10-header-inner">
          <Job10Logo />

          <nav>
            <ul className="job10-nav-menu">
              {navItems.map((item, idx) => (
                <li key={idx}>
                  <a
                    href={item.href}
                    className={`job10-nav-link ${item.active ? 'active' : ''}`}
                    onClick={(e) => handleNavClick(item.href, e)}
                  >
                    {item.label}
                  </a>
                </li>
              ))}
            </ul>
          </nav>

          <a href={ctaHref} className="job10-btn-pill-gradient">
            {ctaLabel}
          </a>

          <button
            className="job10-mobile-toggle"
            aria-label="Toggle mobile menu"
            aria-expanded={mobileMenuOpen}
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          >
            {mobileMenuOpen ? (
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M18 6L6 18M6 6l12 12" />
              </svg>
            ) : (
              <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <path d="M4 6h16M4 12h16M4 18h16" />
              </svg>
            )}
          </button>
        </div>

        {mobileMenuOpen && (
          <div className="job10-mobile-menu" role="dialog" aria-modal="true" aria-label="Mobile Navigation">
            <ul className="job10-mobile-nav-list">
              {navItems.map((item, idx) => (
                <li key={idx}>
                  <a
                    href={item.href}
                    className={`job10-mobile-nav-link ${item.active ? 'active' : ''}`}
                    onClick={(e) => {
                      setMobileMenuOpen(false);
                      handleNavClick(item.href, e);
                    }}
                  >
                    {item.label}
                  </a>
                </li>
              ))}
            </ul>
            <div className="job10-mobile-cta-wrap">
              <a
                href={ctaHref}
                className="job10-btn-pill-gradient job10-mobile-cta"
                onClick={() => setMobileMenuOpen(false)}
              >
                {ctaLabel}
              </a>
            </div>
          </div>
        )}
      </div>
    </header>
  );
};
